profiles.multi-node:
resources:
  # Bigger clusters, bigger backup item lists.
  requests: {cpu: 50m, memory: 128Mi}
  limits: {memory: 1Gi}

profiles.single-node:
resources:
  # Idle between backups; chart sets none.
  requests: {cpu: 20m, memory: 64Mi}
  limits: {memory: 512Mi}

smoke.manifest:
apiVersion: velero.io/v1
kind: BackupStorageLocation
metadata: {name: smoke-without-ca, namespace: velero}
spec:
  provider: aws
  objectStorage: {bucket: e2e}
  config: {region: us-east-1, s3ForcePathStyle: "true", s3Url: "https://s3.catalog-e2e-s3.svc"}
